import gurobipy as gp
from gurobipy import GRB

# Sets
warehouses = [1, 2, 3]
products = [1, 2, 3]
locations = [1, 2, 3, 4, 5, 6, 7]

# Parameters
inventory = {
    1: [600, 900, 750],
    2: [500, 1500, 1200],
    3: [800, 1100, 100]
}

demands = {
    1: [200, 400, 300],
    2: [300, 800, 50],
    3: [200, 300, 50],
    4: [75, 250, 80],
    5: [600, 700, 200],
    6: [225, 850, 100],
    7: [300, 200, 200]
}

cost = {
    1: {  # Warehouse 1
        1: [30, 10, 8, 10, 11, 71, 6],
        2: [39, 14, 11, 14, 16, 82, 8],
        3: [41, 15, 12, 16, 17, 86, 8]
    },
    2: {  # Warehouse 2
        1: [22, 7, 10, 7, 21, 82, 13],
        2: [27, 9, 12, 9, 26, 95, 17],
        3: [29, 9, 13, 9, 28, 99, 18]
    },
    3: {  # Warehouse 3
        1: [19, 11, 12, 10, 25, 83, 15],
        2: [24, 14, 17, 13, 28, 99, 20],
        3: [26, 14, 17, 13, 31, 104, 20]
    }
}

# Model
model = gp.Model(env=env)

# Decision variables: x[w,p,l] >= 0
x = {}
for w in warehouses:
    for p in products:
        for l in locations:
            var = model.addVar(vtype=GRB.CONTINUOUS, name=f"x_{w}_{p}_{l}")
            x[(w, p, l)] = var
model.update()

# Objective: minimize total transportation cost
obj = gp.quicksum(cost[w][p][l-1] * x[(w, p, l)] for w in warehouses for p in products for l in locations)
model.setObjective(obj, GRB.MINIMIZE)

# Constraints

# Inventory constraints
for w in warehouses:
    for p in products:
        model.addConstr(
            gp.quicksum(x[(w, p, l)] for l in locations) <= inventory[w][p-1],
            name=f"inv_w{w}_p{p}"
        )

# Demand constraints
for l in locations:
    for p in products:
        model.addConstr(
            gp.quicksum(x[(w, p, l)] for w in warehouses) == demands[l][p-1],
            name=f"demand_l{l}_p{p}"
        )

# Shipment limit per warehouse-location pair
for w in warehouses:
    for l in locations:
        model.addConstr(
            gp.quicksum(x[(w, p, l)] for p in products) <= 625,
            name=f"limit_w{w}_l{l}"
        )

# Optimize
model.optimize()

# Output final objective if optimal
if model.status == GRB.Status.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
