import gurobipy as gp
from gurobipy import GRB
import math

# Data
coords = {
    0: (0, 0),
    1: (3, -8),
    2: (-10, -5),
    3: (3, 0),
    4: (-3, -3),
    5: (5, -1),
    6: (-7, 3),
    7: (5, -3),
    8: (4, -5),
    9: (6, 4),
    10: (3, 1),
    11: (-10, 0),
    12: (-2, 7),
    13: (-6, -3),
    14: (-8, -7),
    15: (-1, 8)
}
demand = {
    1: 20,
    2: 20,
    3: 28,
    4: 12,
    5: 30,
    6: 24,
    7: 30,
    8: 12,
    9: 27,
    10: 26,
    11: 21,
    12: 20,
    13: 12,
    14: 16,
    15: 19
}
nodes = list(coords.keys())
num_trucks = 4
capacity = 100
max_distance = 45

# Precompute Euclidean distances
dist = {}
for i in nodes:
    for j in nodes:
        if i != j:
            xi, yi = coords[i]
            xj, yj = coords[j]
            dist[(i, j)] = math.hypot(xi - xj, yi - yj)

# Create model
model = gp.Model(env=env)

# Decision variables
y = {}
for k in range(num_trucks):
    for i in nodes:
        for j in nodes:
            if i != j:
                y[(i, j, k)] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{j}_{k}")

# Flow variables (load after visiting node i by truck k)
f = {}
for k in range(num_trucks):
    for i in nodes:
        if i != 0:
            f[(i, k)] = model.addVar(vtype=GRB.CONTINUOUS, lb=0, ub=capacity, name=f"f_{i}_{k}")

# Constraints

# Each node visited exactly once
for j in nodes:
    if j == 0:
        continue
    model.addConstr(
        gp.quicksum(y[(i, j, k)] for k in range(num_trucks) for i in nodes if i != j) == 1,
        name=f"visit_once_{j}"
    )

# Each truck starts and ends at depot
for k in range(num_trucks):
    model.addConstr(
        gp.quicksum(y[(0, j, k)] for j in nodes if j != 0) == 1,
        name=f"start_{k}"
    )
    model.addConstr(
        gp.quicksum(y[(i, 0, k)] for i in nodes if i != 0) == 1,
        name=f"end_{k}"
    )

# Flow balance at each node for each truck
for k in range(num_trucks):
    for j in nodes:
        if j == 0:
            continue
        inc = gp.quicksum(y[(i, j, k)] for i in nodes if i != j)
        out = gp.quicksum(y[(j, l, k)] for l in nodes if l != j)
        model.addConstr(inc == out, name=f"flow_balance_{j}_{k}")
        model.addConstr(inc <= 1, name=f"visit_at_most_once_{j}_{k}")

# Load constraints
# From depot to first node
for k in range(num_trucks):
    for j in nodes:
        if j == 0:
            continue
        model.addConstr(
            f[(j, k)] >= demand[j] - capacity * (1 - y[(0, j, k)]),
            name=f"load_start_{j}_{k}"
        )

# Between nodes
for k in range(num_trucks):
    for i in nodes:
        if i == 0:
            continue
        for j in nodes:
            if j == 0 or j == i:
                continue
            model.addConstr(
                f[(j, k)] >= f[(i, k)] + demand[j] - capacity * (1 - y[(i, j, k)]),
                name=f"load_flow_{i}_{j}_{k}"
            )

# Ensure load is zero if node not visited
for k in range(num_trucks):
    for i in nodes:
        if i == 0:
            continue
        out_sum = gp.quicksum(y[(i, j, k)] for j in nodes if j != i)
        model.addConstr(
            f[(i, k)] <= capacity * out_sum,
            name=f"load_outbound_{i}_{k}"
        )
        model.addConstr(
            f[(i, k)] >= demand[i] * out_sum,
            name=f"load_inbound_{i}_{k}"
        )

# Route length constraints
for k in range(num_trucks):
    model.addConstr(
        gp.quicksum(dist[(i, j)] * y[(i, j, k)] for i in nodes for j in nodes if i != j) <= max_distance,
        name=f"max_dist_{k}"
    )

# Objective: minimize total distance
model.setObjective(
    gp.quicksum(dist[(i, j)] * y[(i, j, k)] for k in range(num_trucks) for i in nodes for j in nodes if i != j),
    GRB.MINIMIZE
)

# Optimize
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal}")
else:
    print("FINAL_OBJECTIVE=INFEASIBLE")
