import gurobipy as gp
from gurobipy import GRB
import math

# Coordinates: depot (0) and communities 1..10
coords = {
    0: (0.0, 0.0),
    1: (3.5, 4.2),
    2: (-2.1, 5.6),
    3: (4.8, -3.2),
    4: (-3.6, -2.8),
    5: (5.2, 2.4),
    6: (-4.1, 3.7),
    7: (2.8, -4.5),
    8: (6.3, -2.1),
    9: (-5.2, -1.8),
    10: (3.9, 5.8)
}

n = 10  # number of communities
nodes = list(range(n + 1))  # 0..10

# Precompute Euclidean distances
dist = {}
for i in nodes:
    for j in nodes:
        if i < j:
            xi, yi = coords[i]
            xj, yj = coords[j]
            dist[(i, j)] = math.hypot(xi - xj, yi - yj)

# Create environment and model
env = gp.Env()
model = gp.Model(env=env)

