        ('C', '1'): 18, ('C', '2'): 24, ('C', '3'): 28, ('C', '4'): 14
    }
    demand = {'1': 200, '2': 300, '3': 400, '4': 500}
    total_demand = sum(demand.values())

    # Decision variables: tons shipped from farm i to store j
    x = m.addVars(farms, stores, name='x', lb=0)

    # Objective: minimize total cost (production + transportation)
    m.setObjective(
        gp.quicksum((prod_cost[i] + trans_cost[(i, j)]) * x[i, j]
