        m.addConstr(gp.quicksum(x[i, j] for j in stores) <= capacity[i],
                    name=f'supply_{i}')

    # Demand satisfaction constraints
    for j in stores:
        m.addConstr(gp.quicksum(x[i, j] for i in farms) == demand[j],
                    name=f'demand_{j}')

