import gurobipy as gp
from gurobipy import GRB

def main():
    env = gp.Env()
    model = gp.Model(env=env)

    # Sets
    areas = [1, 2, 3]
    hotspots = [1, 2, 3]

    # Parameters
    demand = {1: 30, 2: 50, 3: 40}
    available = {1: 25, 2: 40, 3: 35}
    cost = {
        (1, 1): 16, (1, 2): 28, (1, 3): 24,
        (2, 1): 20, (2, 2): 12, (2, 3): 32,
        (3, 1): 24, (3, 2): 20, (3, 3): 16
    }

    # Decision variables
    x = {}
    for i in areas:
        for j in hotspots:
            x[i, j] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_{i}_{j}")

    s = {}
    for j in hotspots:
        s[j] = model.addVar(vtype=GRB.CONTINUOUS, lb=0, name=f"s_{j}")

    model.update()

    # Constraints
    # Supply constraints per area
    for i in areas:
        model.addConstr(
            gp.quicksum(x[i, j] for j in hotspots) <= available[i],
            name=f"avail_{i}"
        )

    # Demand constraints per hotspot
    for j in hotspots:
        model.addConstr(
            gp.quicksum(x[i, j] for i in areas) <= demand[j],
            name=f"demand_{j}"
        )

    # Driver supply constraint: sum x <= 0.5 * s^2
    for j in hotspots:
        model.addQConstr(
            gp.quicksum(x[i, j] for i in areas) <= 0.5 * s[j] * s[j],
            name=f"sup_{j}"
        )

    # Objective: maximize profit
    base_rev = gp.quicksum(15 * x[i, j] for i in areas for j in hotspots)
    surcharge_rev = gp.quicksum(s[j] * x[i, j] for i in areas for j in hotspots)
    deadhead_cost = gp.quicksum(cost[(i, j)] * x[i, j] for i in areas for j in hotspots)
    profit = base_rev + surcharge_rev - deadhead_cost
    model.setObjective(profit, GRB.MAXIMIZE)

    # Optimize
    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")

if __name__ == "__main__":
    main()
