    total_spend == gp.quicksum(prices[s][components.index(c)] * x[s, c]
                               for s in suppliers for c in components),
    name="total_spend_def",
)

# Spend share constraints (no more than 40% of total spend per supplier)
for s in suppliers:
    supplier_spend = gp.quicksum(prices[s][components.index(c)] * x[s, c]
                                 for c in components)
