        supplier_spend <= 0.4 * total_spend,
        name=f"share_{s}",
    )

# Objective: minimize total spend
model.setObjective(total_spend, GRB.MINIMIZE)

# Optimize
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
