model = gp.Model(env=env)

# Parameters
zones = ['A', 'B', 'C']
vans = [1, 2]

# Demand per zone (low battery bikes)
demand = {
    'A': 200 * 0.60,  # 120
    'B': 150 * 0.80,  # 120
    'C': 180 * 0.50   # 90
}

dispatch_cost = {1: 300, 2: 320}
capacity = {1: 150, 2: 180}
coeff = {1: 0.08, 2: 0.07}

# Decision variables
x = {}
for v in vans:
    for z in zones:
        x[v, z] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"x_{v}_{z}")

y = {}
for v in vans:
    y[v] = model.addVar(vtype=GRB.BINARY, name=f"y_{v}")

model.update()

# Demand constraints
for z in zones:
    model.addConstr(gp.quicksum(x[v, z] for v in vans) == demand[z], name=f"demand_{z}")

# Capacity constraints
for v in vans:
    model.addConstr(gp.quicksum(x[v, z] for z in zones) <= capacity[v], name=f"cap_{v}")

# Linking constraints: if van used, capacity can be used; otherwise none
for v in vans:
    model.addConstr(gp.quicksum(x[v, z] for z in zones) <= capacity[v] * y[v], name=f"link_{v}")

# Objective: dispatch cost + operational cost (quadratic)
obj = gp.quicksum(dispatch_cost[v] * y[v] for v in vans)
obj += gp.quicksum(coeff[v] * x[v, z] * x[v, z] for v in vans for z in zones)
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
